/**
 * Reports one `dt-app.ai-resource.skill` bizevent per bundled SKILL.md and one
 * `dt-app.ai-resource.reference` bizevent per bundled reference file, after a
 * successful deploy or publish. Reads the rest of its config via
 * `globalConfigModule.getConfig()`. Errors are caught and logged internally so
 * callers can fire-and-forget with `await reportSkillDocuments(...)`.
 *
 * @param shouldSign Whether the archive is being signed (`--sign-archive`).
 * Deliberate deviation from the argument-free `reportStratoComponents`: skill
 * documents are only ever bundled into a signed archive (see
 * `applySkillDocuments` in `build/bundle-skills.ts`), and `signArchive` is a plain
 * commander flag threaded straight into `deploy()`/`publish()` - it never lands in
 * `globalConfigModule`, so this reporter cannot discover it on its own. This
 * parameter must not be "cleaned up" into an argument-free signature.
 */
export declare function reportSkillDocuments(shouldSign: boolean): Promise<void>;
